/// A triangle whose sides are positive, finite and strictly unequal to a
/// degenerate line.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Triangle {
    a: f64,
    b: f64,
    c: f64,
}

impl Triangle {
    /// A triangle, or `None` unless every side is positive and finite and
    /// shorter than the other two together.
    pub fn new(a: f64, b: f64, c: f64) -> Option<Triangle> {
        let sides = [a, b, c];
        if sides.iter().any(|side| !side.is_finite() || *side <= 0.0) {
            return None;
        }
        if a < b + c && b < a + c && c < a + b {
            Some(Triangle { a, b, c })
        } else {
            None
        }
    }
}

impl Shape for Triangle {
    fn area(&self) -> f64 {
        let s = self.perimeter() / 2.0;
        (s * (s - self.a) * (s - self.b) * (s - self.c)).sqrt()
    }

    fn perimeter(&self) -> f64 {
        self.a + self.b + self.c
    }

    fn name(&self) -> &'static str {
        "triangle"
    }
}
